#include "mre_touch.h"
#include "mre_gic.h"
#include <string.h>
static void touch_irq_handler(uint32_t irq,void *context){(void)irq;mre_touch_irq((mre_touch_device_t *)context);}
mre_status_t mre_touch_register_irq(mre_touch_device_t *dev,uint32_t irq){mre_status_t st;if(!dev)return MRE_E_INVALID;st=mre_gic_register_handler(irq,touch_irq_handler,dev);if(st!=MRE_OK)return st;return mre_gic_enable_irq(irq);}
static uint16_t scale_axis(uint16_t v,uint16_t raw,uint16_t panel){uint32_t n;if(raw==0u||panel==0u)return 0u;if(v>raw)v=raw;n=(uint32_t)v*(uint32_t)(panel-1u);return (uint16_t)(n/raw);}
static void enqueue(mre_touch_device_t *d,const mre_input_event_t *e){uint32_t next=(d->head+1u)%MRE_TOUCH_QUEUE_CAPACITY;if(next==d->tail){++d->dropped;return;}d->queue[d->head]=*e;d->head=next;}
mre_status_t mre_touch_init(mre_touch_device_t *d,const mre_touch_ops_t *ops,const mre_touch_transform_t *t){if(!d||!ops||!ops->read_frame||!t||!t->raw_max_x||!t->raw_max_y||!t->panel_width||!t->panel_height)return MRE_E_INVALID;memset(d,0,sizeof(*d));d->ops=*ops;d->transform=*t;return MRE_OK;}
void mre_touch_irq(mre_touch_device_t *d){if(d)d->irq_pending=1u;}
mre_status_t mre_touch_service(mre_touch_device_t *d,uint64_t ts){mre_touch_frame_t f;uint32_t i;if(!d)return MRE_E_INVALID;if(!d->irq_pending)return MRE_E_NOT_FOUND;d->irq_pending=0u;memset(&f,0,sizeof(f));{mre_status_t st=d->ops.read_frame(&f);if(st!=MRE_OK)return st;}if(f.count>MRE_TOUCH_MAX_CONTACTS)return MRE_E_INVALID;d->timestamp_ns=ts;for(i=0;i<f.count;++i){mre_input_event_t e;uint16_t x=f.contacts[i].x,y=f.contacts[i].y;if(d->transform.swap_xy){uint16_t q=x;x=y;y=q;}x=scale_axis(x,d->transform.swap_xy?d->transform.raw_max_y:d->transform.raw_max_x,d->transform.swap_xy?d->transform.panel_width:d->transform.panel_width);y=scale_axis(y,d->transform.swap_xy?d->transform.raw_max_x:d->transform.raw_max_y,d->transform.panel_height);if(d->transform.flip_x)x=(uint16_t)(d->transform.panel_width-1u-x);if(d->transform.flip_y)y=(uint16_t)(d->transform.panel_height-1u-y);memset(&e,0,sizeof(e));e.type=MRE_INPUT_TOUCH;e.code=(int32_t)f.contacts[i].id;e.x=x;e.y=y;e.value=f.contacts[i].down?1u:0u;e.timestamp_ns=ts;enqueue(d,&e);}return MRE_OK;}
mre_status_t mre_touch_poll(void *context,mre_input_event_t *e){mre_touch_device_t *d=(mre_touch_device_t *)context;if(!d||!e)return MRE_E_INVALID;if(d->tail==d->head)return MRE_E_NOT_FOUND;*e=d->queue[d->tail];d->tail=(d->tail+1u)%MRE_TOUCH_QUEUE_CAPACITY;return MRE_OK;}
